                id="keyboard-disabled",
                no_keyboard=True,
            )
        )


class TestCoreUploadCreateLineCoverageEightQA:
    def test_default_upload_with_multiple_supported_props(self):
        assert_upload(
            Upload.create(
                id="supported-props",
                multiple=False,
                accept={"image/png": [".png"]},
                disabled=False,
            )
        )


class TestCoreUploadCreateLineCoverageNineQA:
    def test_styled_upload_delegates_to_upload_create(self):
        component = StyledUpload.create(
            rx.vstack(rx.text("Styled"), rx.text("Upload")),
            id="styled",
        )

        assert isinstance(component, StyledUpload)
        assert Upload.is_used
        Upload.is_used = False


class TestCoreUploadCreateLineCoverageTenQA:
    def test_upload_namespace_root_delegates_to_upload_create(self):
        assert_upload(
            rx.upload.root(
                rx.text("Namespace root"),
                id="namespace-root",
            )
        )

    @classmethod
    def _update_arg_tuple_for_on_drop(cls, arg_value: tuple[Var, Var]):
        """Helper to update caller-provided EventSpec args for direct use with on_drop.

        Args:
            arg_value: The arg tuple to update (if necessary).

        Returns:
            The updated arg_value tuple when arg is "files", otherwise the original arg_value.
        """
        if arg_value[0]._js_expr == "files":
            placeholder = parse_args_spec(_on_drop_spec)[0]
            return (arg_value[0], placeholder)
        return arg_value

    @staticmethod
    def _get_app_wrap_components() -> dict[tuple[int, str], Component]:
        return {
            (5, "UploadFilesProvider"): UploadFilesProvider.create(),
        }


class StyledUpload(Upload):
    """The styled Upload Component."""

    @classmethod
    def create(cls, *children, **props) -> Component:
        """Create the styled upload component.

        Args:
            *children: The children of the component.
            **props: The properties of the component.

        Returns:
            The styled upload component.
        """
        # Set default props.
        props.setdefault("border", "1px dashed var(--accent-12)")
        props.setdefault("padding", "5em")
        props.setdefault("textAlign", "center")

        # Mark the Upload component as used in the app.
        Upload.is_used = True

        return super().create(
            *children,
            **props,
        )
